-- Add durable story bibles for the six curated StoryHeaven serials.
-- Existing complete active bibles are preserved.

whenever sqlerror exit failure rollback

declare
  procedure seed_bible(
    p_story_id varchar2,
    p_concept clob,
    p_world_rules clob,
    p_characters clob,
    p_timeline clob,
    p_glossary clob,
    p_forbidden clob,
    p_voice clob,
    p_blueprint clob
  ) is
  begin
    merge into storyheaven_serial_bibles target
    using (
      select id as story_id from storyheaven_stories where id = p_story_id
    ) source
       on (target.story_id = source.story_id)
    when matched then update set
      target.bible_version = target.bible_version + 1,
      target.bible_status = 'active',
      target.concept_json = p_concept,
      target.world_rules_json = p_world_rules,
      target.characters_json = p_characters,
      target.timeline_json = p_timeline,
      target.glossary_json = p_glossary,
      target.forbidden_json = p_forbidden,
      target.voice_profile_json = p_voice,
      target.narrative_blueprint_json = p_blueprint,
      target.updated_at = systimestamp
      where target.bible_status <> 'active'
         or target.world_rules_json is null
         or target.characters_json is null
         or target.narrative_blueprint_json is null
    when not matched then insert (
      story_id, bible_version, bible_status, concept_json,
      world_rules_json, characters_json, timeline_json, glossary_json,
      forbidden_json, voice_profile_json, narrative_blueprint_json
    ) values (
      source.story_id, 1, 'active', p_concept,
      p_world_rules, p_characters, p_timeline, p_glossary,
      p_forbidden, p_voice, p_blueprint
    );
  end;
begin
  seed_bible(
    'seed-last-platform',
    q'~{"title":"8초를 싣는 막차","logline":"사라진 동생의 마지막 8초를 숨겨 온 기억 청소부가 정차할 때마다 기억을 빼앗는 회수 열차에 오른다.","synopsis":"자정 이후 버려진 기억이 잔향으로 고이는 해원시에서 기억 청소부 서이결은 실종된 동생의 마지막 8초를 몰래 간직한다. 봉쇄 승강장에 나타난 회수 열차와 13번 감사관을 따라가며 각 역의 기억 사건을 해결하고 동생의 실종, 감사국의 목적, 도시 최초의 8초를 추적한다.","genres":["현대판타지","도시미스터리"],"tags":["기억","괴이열차","감사국"],"rating":"teen","readerPromise":"매 화 새로운 역의 기억 사건을 해결하면서 동생과 도시의 비밀에 가까워진다.","familiarPleasure":"규칙이 있는 괴이 공간 탐사와 단서 회수, 가족을 되찾으려는 추적의 쾌감","novelTwist":"열차의 통행료는 돈이 아니라 탑승자가 소중히 여기는 기억이며 잃은 기억이 현실을 바꾼다.","targetAge":"teen"}~',
    q'~["자정 이후 해원시에서 버려진 기억은 물기와 소리 같은 잔향으로 남는다.","기억 청소부는 잔향을 수거할 수 있지만 개인 기억을 숨기면 감사국의 처벌 대상이 된다.","회수 열차는 지워진 사람의 이름이 남은 역에만 정차한다.","열차 문을 열거나 다음 칸으로 이동할 때 탑승자는 소중한 기억 하나를 통행료로 잃는다.","잃은 기억은 단순 망각이 아니라 관계와 기록 일부를 현실에서 바꾼다.","동생의 마지막 8초는 여러 조각으로 나뉘어 역과 승객에게 남아 있다.","13번 감사관은 열차의 붕괴를 막아야 하지만 감사국의 명령을 전부 신뢰하지 않는다."]~',
    q'~[{"id":"seo-igyeol","name":"서이결","role":"기억 청소부이자 주인공","desire":"실종된 동생을 찾아 마지막 8초의 진실을 확인한다.","fear":"동생을 찾기 전에 동생을 사랑했다는 기억부터 잃는 것","secret":"감사국에 반납해야 할 동생의 마지막 8초를 숨기고 있다.","knowledge":["기억 잔향 수거법","봉쇄 승강장 비상 통로"]},{"id":"auditor-13","name":"13번 감사관","role":"회수 열차를 감시하는 조력자 겸 감시자","desire":"열차 붕괴를 막고 감사국이 숨긴 운행 목적을 밝힌다.","fear":"자신 역시 기록에서 지워진 사람이라는 사실이 드러나는 것","secret":"공식 감사관 명부에 존재하지 않는다.","knowledge":["열차 통행료 규칙","감사국의 일부 삭제 기록"]},{"id":"seo-ihyeon","name":"서이현","role":"실종된 동생이자 장기 미스터리의 중심","desire":"누나가 자신을 찾기 전에 최초의 8초를 멈춘다.","fear":"자신을 구하면 해원시 전체가 지워지는 것","secret":"실종이 아니라 열차 운행을 붙잡기 위해 스스로 남았다.","knowledge":["최초 운행 사고","감사국 창설 이전 기록"]}]~',
    q'~["3년 전 서이현이 봉쇄 승강장에서 실종되고 서이결은 마지막 8초를 숨긴다.","현재 회수 열차가 폐쇄된 승강장에 다시 나타난다.","이결은 첫 통행료를 내고 지워진 사람들의 이름이 실린 객차로 들어간다.","각 역의 사건이 동생의 8초와 감사국의 삭제 작업으로 연결된다.","장기적으로 최초 운행일의 선택과 해원시가 유지되는 대가가 밝혀진다."]~',
    q'~["기억 잔향: 강한 감정이 물기와 소리처럼 공간에 남은 흔적","회수 열차: 삭제된 기억과 이름을 운반하는 자정의 열차","통행료: 객차 이동 때 현실에서 함께 사라지는 개인 기억","감사국: 기억 재난을 관리한다고 주장하는 비공개 기관"]~',
    q'~["서이결은 동생의 마지막 8초를 자발적으로 버린 적이 없다.","잃은 기억은 아무 대가 없이 원상 복구되지 않는다.","13번 감사관을 평범한 현직 공무원으로 확정하지 않는다.","회수 열차는 낮이나 일반 승강장에 아무 조건 없이 나타나지 않는다.","동생의 생존 여부를 단서 없이 번복하지 않는다."]~',
    q'~{"narratorDistance":"서이결의 감각과 판단에 밀착한 3인칭 제한 시점","sentenceRhythm":"추적 장면은 짧고 선명하게, 기억의 감정 장면은 호흡을 조금 늘인다.","dialogueRatio":38,"humorStyle":"긴장을 깨지 않는 건조한 현장 농담","descriptionDensity":62,"emotionStyle":"감정을 직접 선언하기보다 사라진 사물과 어긋난 습관으로 보여준다.","sensoryPalette":"젖은 철 냄새, 형광등 떨림, 바퀴 마찰음, 차가운 유리와 잔향의 물기","visualizationRules":["장면마다 인물 위치와 출구를 먼저 제시한다.","기억이 사라질 때 현실에서 달라진 물건 하나를 즉시 보여준다.","열차 규칙은 행동과 결과를 같은 장면 안에서 연결한다."],"forbiddenHabits":["추상적인 운명 설명 반복","같은 기억 상실 반전 연속 사용","영문 번역투 대사"]}~',
    q'~{"informationStrategy":"각 역의 독립 사건에서 작은 답을 완결하고 동생의 8초에 관한 단서 하나를 남긴다. 감사국과 13번 감사관의 정보는 서로 모순되는 기록을 통해 단계적으로 공개한다.","openingModes":["열차 규칙이 어긋난 현장","사라진 기억 때문에 바뀐 일상","새 역의 구조 요청"],"signatureTechniques":["소중한 기억을 선택해야 하는 제한 선택","사라진 사물로 감정의 빈자리 시각화","마지막 8초의 짧은 장면을 매번 다른 관점으로 복원"],"escalationPattern":"개인 기억 손실에서 관계의 삭제, 도시 기록의 변형, 해원시 존속의 대가 순으로 범위를 넓힌다.","revealCadence":"매 화 사건의 답 하나와 장기 단서 하나를 제공하고 3화마다 기존 단서의 의미를 뒤집는다.","antiRepetitionRules":["두 화 연속 같은 종류의 기억을 통행료로 쓰지 않는다.","매번 객차 안 추격으로 해결하지 않는다.","동생의 환영만으로 끝내는 훅을 반복하지 않는다."]}~'
  );

  seed_bible(
    'seed-rain-memory',
    q'~{"title":"비를 보관하는 잡화점","logline":"기억을 빗물에 담아주는 가게에 아직 태어나지 않은 딸이 사흘 뒤의 화재를 품은 병을 들고 찾아온다.","synopsis":"기억이 비가 되어 내리는 골목의 우천상회에서 장예슬은 손님이 잊고 싶은 날을 병에 보관한다. 미래의 딸이라는 아이와 금지된 빗물 병을 계기로 관리청의 추적을 피하며 유년기의 공백, 실종된 연인, 아이가 태어날 수 있는 시간선을 찾는다.","genres":["감성판타지","시간미스터리"],"tags":["비","기억가게","미래의딸"],"rating":"all","readerPromise":"매 화 한 병에 담긴 기억을 풀어 주며 따뜻한 여운과 미래 화재의 단서를 함께 얻는다.","familiarPleasure":"사연 있는 손님을 돕는 가게형 에피소드와 가족 미스터리","novelTwist":"잊은 기억은 비로 보관되며 미래에서 온 비는 현재의 날씨와 시간선을 바꾼다.","targetAge":"all"}~',
    q'~["강한 기억은 특정한 비가 되어 우천상회의 병에 담긴다.","병을 열면 기억의 주인뿐 아니라 주변 날씨와 관계에도 영향이 생긴다.","아직 일어나지 않은 미래의 비는 관리청이 금지하며 존재 자체가 시간선 위반이다.","장예슬은 손님 동의 없이 기억 병을 열거나 팔 수 없다.","지하 선반에는 예슬 자신의 유년기와 실종된 연인에 관한 회수 금지 병이 있다.","미래의 딸은 한 시간선에서만 태어날 수 있으며 현재에 오래 머물수록 모습이 흐려진다.","기억을 되돌려도 그동안 내린 선택과 상처까지 자동으로 사라지지는 않는다."]~',
    q'~[{"id":"jang-yeseul","name":"장예슬","role":"우천상회 주인이자 주인공","desire":"손님의 기억을 지키면서 미래의 딸과 잃어버린 과거를 살린다.","fear":"자신의 선택 때문에 아이가 태어날 미래가 사라지는 것","secret":"유년기의 핵심 기억을 스스로 지하 선반에 봉인했다.","knowledge":["기억비 감별법","병의 개봉과 봉인 규칙"]},{"id":"haeon","name":"해온","role":"미래에서 온 아이","desire":"사흘 뒤 화재를 막고 자신의 시간선을 지킨다.","fear":"엄마가 진실을 알면 자신을 포기할 것","secret":"화재를 막는 것만이 방문 목적은 아니다.","knowledge":["사흘 뒤의 화재","미래 우천상회의 일부 모습"]},{"id":"inspector-mok","name":"목재인","role":"기억기상관리청 회수관","desire":"미래의 비가 현재를 오염시키기 전에 전부 회수한다.","fear":"과거에 은폐한 시간선 사고가 드러나는 것","secret":"예슬의 실종 연인과 같은 사건에 연루됐다.","knowledge":["금지 비 목록","관리청 시간선 봉쇄 절차"]}]~',
    q'~["어린 예슬이 기억 일부를 병에 봉인하고 우천상회의 후계가 된다.","연인이 실종된 날의 비가 관리청에 의해 회수된다.","현재 맑은 날 해온이 미래 화재가 담긴 병을 들고 찾아온다.","예슬이 손님들의 병을 해결하며 화재 원인과 시간선 밀거래를 추적한다.","미래의 아이가 존재할 조건과 예슬이 봉인한 선택이 하나로 연결된다."]~',
    q'~["기억비: 감정과 장면이 물성으로 변한 비","우천상회: 기억비를 보관하고 주인에게 돌려주는 잡화점","미래비: 아직 일어나지 않은 기억이 담겨 금지된 병","관리청: 기억 날씨와 시간선 오염을 통제하는 기관"]~',
    q'~["해온을 평범한 현재의 아동으로 처리하지 않는다.","기억 병은 주인의 사연과 무관한 만능 해결 도구가 아니다.","장예슬은 손님 동의 없는 기억 거래를 선의로 정당화하지 않는다.","실종된 연인의 정체를 근거 없이 매 화 바꾸지 않는다.","따뜻한 에피소드 뒤에 동일한 화재 환상만 반복하지 않는다."]~',
    q'~{"narratorDistance":"장예슬을 중심으로 손님의 감정에 잠시 가까워지는 따뜻한 3인칭","sentenceRhythm":"일상은 편안하게 읽히고 기억 병이 열릴 때 짧은 감각 문장으로 전환한다.","dialogueRatio":44,"humorStyle":"가게 단골과 물건에서 나오는 생활형 미소","descriptionDensity":58,"emotionStyle":"위로를 설교하지 않고 손님이 기억을 간직하거나 놓는 행동으로 마무리한다.","sensoryPalette":"빗소리, 유리병의 냉기, 젖은 흙 냄새, 처마의 노란 불빛","visualizationRules":["병마다 색과 빗소리를 다르게 부여한다.","기억 장면과 현재 가게의 물건을 시각적으로 연결한다.","시간선 변화는 골목의 작은 차이부터 보여준다."],"forbiddenHabits":["과도한 감상적 독백","모든 사연을 죽음으로 해결","미래 설정 설명만 이어지는 장면"]}~',
    q'~{"informationStrategy":"손님 에피소드의 감정적 완결과 해온의 시간선 단서를 병렬로 전개한다. 예슬의 과거는 지하 선반의 병을 한 칸씩 열며 복원한다.","openingModes":["이상한 날씨와 함께 온 손님","라벨이 바뀐 기억 병","해온이 기억하는 미래의 일상"],"signatureTechniques":["병 속 기억과 현재 사물의 매치 컷","선택에 따라 달라지는 골목의 작은 변화","비가 그친 뒤 남는 한 문장짜리 여운"],"escalationPattern":"개인 사연에서 골목의 시간 변화, 관리청의 은폐, 해온이 존재하는 유일한 미래로 확장한다.","revealCadence":"매 화 손님의 질문은 해결하고 예슬의 과거 또는 화재에 관한 새 정보 하나를 남긴다.","antiRepetitionRules":["연속해서 가족 사별 사연을 쓰지 않는다.","모든 병을 실수로 깨뜨려 사건을 시작하지 않는다.","해온이 정답을 미리 말해 해결하지 않는다."]}~'
  );

  seed_bible(
    'seed-night-auditor',
    q'~{"title":"13번 야간 감사관","logline":"괴물의 민원을 심사하는 말단 감사관이 자기 이름으로 접수된 사망 후 근무 취소 신청서를 발견한다.","synopsis":"도시가 잠든 뒤에만 열리는 시청 지하 13층에서 도세림은 인간인 척 살아가는 존재들의 민원을 심사한다. 존재할 수 없는 13번 번호표와 자신의 사망 기록을 단서로 주민을 바꾸는 조직, 민원실에 자신을 묶어 둔 계약, 진짜 주민 명부를 추적한다.","genres":["오피스괴담","미스터리"],"tags":["야간민원실","규칙괴담","사망기록"],"rating":"teen","readerPromise":"기묘하지만 논리적인 민원 한 건을 해결할 때마다 주인공의 사망과 도시 명부의 비밀이 열린다.","familiarPleasure":"규칙 괴담의 긴장과 공무원식 절차로 초자연 사건을 해결하는 통쾌함","novelTwist":"괴물도 시민 자격과 민원을 가지며 잘못된 행정 처리가 사람과 괴물의 자리를 실제로 바꾼다.","targetAge":"teen"}~',
    q'~["지하 13층 민원실은 자정부터 해 뜨기 전까지만 열린다.","민원인은 번호표와 사실에 맞는 서류를 제출해야 하며 거짓 서류는 신체 일부를 대가로 고친다.","감사관이 접수 도장을 찍으면 민원 내용은 현실의 시민 자격에 반영된다.","13번 번호표는 공식 발급 목록에 없으며 나타날 때마다 주민 교체 사건이 일어난다.","도세림은 근무 중 민원실 경계를 벗어날 수 없고 해가 뜨면 전날의 일부 기억을 잃는다.","진짜 주민 명부는 사람과 비인간의 원래 이름을 함께 기록한다.","절차를 무시한 선의는 더 큰 행정 재난을 만들며 해결에는 규칙의 빈틈을 정확히 써야 한다."]~',
    q'~[{"id":"do-serim","name":"도세림","role":"야간 감사관이자 주인공","desire":"자신의 사망 기록과 민원실 계약의 진실을 밝힌다.","fear":"이미 죽은 자신이 다른 사람의 자리를 빼앗아 살고 있다는 결론","secret":"3년 전 사망 후 근무 취소 신청서가 본인 명의로 접수돼 있다.","knowledge":["야간 민원 규정","문서 위조 흔적 감별"]},{"id":"clerk-gong","name":"공칠복","role":"규정에 집착하는 선임 주무관","desire":"어떤 희생이 있어도 민원실의 업무 연속성을 지킨다.","fear":"진짜 주민 명부가 공개되어 자신의 임용 경로가 드러나는 것","secret":"세림이 들어오기 전에도 같은 이름의 감사관을 교육했다.","knowledge":["폐기된 규정집","13번 창구의 과거"]},{"id":"ticket-13","name":"13번 민원인","role":"주민 자격 반환을 요구하는 반복 등장 인물","desire":"빼앗긴 인간 자격과 이름을 되찾는다.","fear":"세림이 자신을 기억해 내는 것","secret":"세림의 사망과 주민 교체 사건을 직접 목격했다.","knowledge":["진짜 주민 명부 위치","세림의 생전 마지막 민원"]}]~',
    q'~["3년 전 도세림의 사망과 같은 날 지하 13층에서 대규모 주민 명부 수정이 일어난다.","세림은 사망 사실을 잊은 채 야간 감사관으로 근무한다.","현재 13번 번호표 민원인이 인간 자격 반환을 요구한다.","세림이 자기 명의의 사망 후 근무 취소 신청서를 발견한다.","민원 사건을 해결할수록 조직적인 주민 교체와 계약의 원본에 접근한다."]~',
    q'~["시민 자격: 도시가 사람으로 인정하고 기록과 기억을 연결해 주는 행정 상태","13번 번호표: 공식 목록 밖에서 발급되는 주민 교체 사건의 신호","진짜 주민 명부: 현재 신분과 원래 존재를 함께 적은 비공개 장부","사망 후 근무: 사망 처리 뒤에도 계약 때문에 직무가 유지되는 상태"]~',
    q'~["야간 민원 규칙은 편의에 따라 갑자기 바뀌지 않는다.","도세림의 사망은 단순 꿈이나 장난 서류로 무효화하지 않는다.","모든 민원인을 악의적인 괴물로 묘사하지 않는다.","행정 용어만 나열하고 구체적인 위험을 생략하지 않는다.","13번 민원인의 정체를 근거 없이 반복 반전하지 않는다."]~',
    q'~{"narratorDistance":"도세림의 관찰과 추리에 붙은 3인칭 제한 시점","sentenceRhythm":"업무 대화는 빠르고 건조하게, 규칙 위반 순간은 짧은 문장으로 끊는다.","dialogueRatio":52,"humorStyle":"공포 상황에서도 서식과 결재선을 따지는 블랙 오피스 유머","descriptionDensity":48,"emotionStyle":"세림의 불안을 업무 습관과 틀린 서명, 기억 공백으로 드러낸다.","sensoryPalette":"낡은 형광등, 도장 잉크 냄새, 복사기 열기, 빈 복도의 구두 소리","visualizationRules":["규칙마다 위반 전후의 물리적 변화를 보여준다.","민원인의 비인간성은 작은 어긋남부터 확대한다.","추리는 서류 단서와 현장 결과를 나란히 배치한다."],"forbiddenHabits":["규칙을 독자에게 숨긴 뒤 처벌","설명 없는 갑작스러운 괴물 출현","모든 대사를 관공서 말투로 통일"]}~',
    q'~{"informationStrategy":"매 화 민원 서류의 표면적 요구와 숨은 진짜 요구를 분리해 추리한다. 세림의 사망 기록은 서명, 결재선, 누락된 날짜를 모아 복원한다.","openingModes":["불가능한 민원 서류 접수","규정과 다른 번호표 호출","평범한 동료의 행정 기록 오류"],"signatureTechniques":["공문서 한 줄이 현실을 바꾸는 즉시 결과","규정의 빈틈을 이용한 역전 처리","결재 도장 소리와 함께 드러나는 짧은 공포"],"escalationPattern":"개별 시민 자격 오류에서 부서 단위 교체, 도시 주민 명부 조작, 세림 자신의 존재 계약으로 확장한다.","revealCadence":"민원 한 건은 매 화 종결하고 세림의 과거 서류 조각 하나를 확보하며 3화마다 신뢰하던 규정 하나의 목적을 뒤집는다.","antiRepetitionRules":["같은 번호표 오류로 연속 시작하지 않는다.","도장 한 번으로 모든 갈등을 해결하지 않는다.","민원인의 외형 반전만으로 훅을 끝내지 않는다."]}~'
  );

  seed_bible(
    'seed-rescue-window',
    q'~{"title":"구조 요청은 한 번만","logline":"하루 한 번 공간을 여는 구조사가 동생 대신 낯선 아이를 구하자 미래의 동생이 두 번째 창을 열고 경고한다.","synopsis":"한유진은 벽 하나를 재난 현장과 연결하는 구조창을 하루 한 번 열 수 있다. 창을 열 때마다 도시의 실제 길 하나가 사라진다. 동생과 낯선 아이 사이에서 아이를 구한 뒤 나타난 미래의 시계와 두 번째 창을 따라 도시의 길을 먹는 존재와 가족의 미래를 추적한다.","genres":["재난판타지","시간미스터리"],"tags":["구조창","선택의대가","가족"],"rating":"teen","readerPromise":"매 화 제한된 정보와 한 번의 구조 기회 속에서 누굴 구할지 선택하고 그 대가가 다음 재난으로 이어진다.","familiarPleasure":"시간 제한 구조 작전과 어려운 선택, 가족 미스터리의 긴장","novelTwist":"공간을 잇는 구조창을 열 때마다 도시의 길뿐 아니라 사람 사이의 기억 경로도 사라진다.","targetAge":"teen"}~',
    q'~["한유진은 원칙적으로 하루에 구조창을 한 번만 열 수 있다.","구조창은 유진이 좌표와 대상의 생존 신호를 확인한 벽에만 열린다.","창이 열릴 때 도시의 실제 길 하나가 하루 이상 사라진다.","두 번째 창은 정상 능력이 아니라 미래 또는 외부 존재의 개입이다.","사라지는 길은 도로에서 기억과 관계의 경로로 점차 확장될 수 있다.","구조 대상의 목소리와 기억은 재난 존재에 의해 위조될 수 있다.","선택하지 못한 구조 신호도 소멸하지 않고 이후 사건의 결과로 돌아온다."]~',
    q'~[{"id":"han-yujin","name":"한유진","role":"도시재난구조국 구조사이자 주인공","desire":"단 한 번의 창으로 최대한 많은 생명을 살리고 동생의 미래를 지킨다.","fear":"구조 선택이 가족과 도시의 길을 영구히 지우는 것","secret":"과거 첫 구조창 사고에서 사라진 길의 진짜 대가를 숨겼다.","knowledge":["구조창 좌표 계산","재난 생존 신호 판독"]},{"id":"han-jaeon","name":"한재온","role":"유진의 동생이자 시간선 미스터리의 중심","desire":"유진이 특정 구조를 반복하지 못하게 막는다.","fear":"미래의 자신이 가족을 속이는 존재로 바뀌는 것","secret":"여러 미래 시간선에서 서로 다른 기억을 유진에게 보냈다.","knowledge":["첫 구조창 사고의 가족 기록","미래에 사라질 길 목록"]},{"id":"seo-u","name":"서우","role":"첫 선택에서 구한 아이","desire":"자신을 따라오는 가짜 아버지에게서 벗어난다.","fear":"구조될 때 함께 건너온 존재가 유진의 가족을 차지하는 것","secret":"사람의 말에서 시간선이 다른 부분을 구별한다.","knowledge":["두 번째 창의 징후","가짜 재온의 습관"]}]~',
    q'~["과거 한유진의 첫 구조창으로 가족에게 이어지는 길 하나가 손상된다.","현재 동생과 낯선 아이의 구조 신호가 동시에 발생한다.","유진은 아이 서우를 선택하고 동생을 구하지 못한다.","미래의 재온과 닮은 존재가 두 번째 창을 열어 도시 소멸을 경고한다.","구조 작전이 반복될수록 사라진 길과 조작된 가족 기억의 원인이 드러난다."]~',
    q'~["구조창: 벽을 원격 재난 현장과 잠시 연결하는 공간","길 소실: 구조의 대가로 도로나 관계의 연결이 지워지는 현상","두 번째 창: 하루 한 번 규칙을 깨고 외부에서 열린 비정상 통로","시간 손목시계: 미래 구조 기록과 남은 선택 시간을 보여주는 장치"]~',
    q'~["한유진은 아무 제한 없이 연속해서 구조창을 열 수 없다.","구조의 대가는 다음 날 아무 설명 없이 완전히 복구되지 않는다.","재온과 가짜 재온의 차이는 독자가 확인할 행동 단서 없이 결정하지 않는다.","서우를 수동적인 구조 대상에만 머물게 하지 않는다.","매 화 동생과 타인 중 하나만 고르는 동일한 선택을 반복하지 않는다."]~',
    q'~{"narratorDistance":"한유진의 현장 판단에 밀착하되 구조 대상의 짧은 시점을 제한적으로 삽입","sentenceRhythm":"카운트다운은 짧고 빠르게, 선택 직후에는 사라진 길의 결과를 차분히 보여준다.","dialogueRatio":43,"humorStyle":"구조대 동료 사이의 짧은 긴장 완화","descriptionDensity":55,"emotionStyle":"죄책감을 독백으로 반복하지 않고 지도에서 지워진 길과 달라진 가족 습관으로 표현한다.","sensoryPalette":"경보음, 콘크리트 분진, 손목시계 진동, 창 가장자리의 차가운 빛","visualizationRules":["구조 현장의 공간 배치와 위험 요소를 먼저 제시한다.","남은 시간을 행동 사이에 구체적으로 갱신한다.","선택 직후 무엇이 사라졌는지 일상 장면으로 확인한다."],"forbiddenHabits":["시간 제한 숫자 오류","구조 장비와 위치가 갑자기 바뀌는 장면","선택의 대가를 다음 화에서 무시"]}~',
    q'~{"informationStrategy":"재난 현장 정보와 조작 가능성을 함께 제시해 독자도 유진과 선택하게 한다. 미래 재온의 진위는 말투, 습관, 기억의 차이를 누적해 판별한다.","openingModes":["두 곳에서 동시에 온 구조 신호","지도에서 사라진 길 발견","구조된 사람이 보내는 미래 경고"],"signatureTechniques":["한 화면에 병치되는 두 구조 현장","카운트다운 직전의 정보 반전","구조 성공 뒤 일상에서 확인되는 예상 밖 대가"],"escalationPattern":"개별 도로 소실에서 가족 기억, 도시 구역 간 연결, 시간선 전체의 귀환 경로로 대가를 키운다.","revealCadence":"매 화 구조 선택의 직접 결과를 보여주고 두 화마다 과거 선택의 진실 한 조각을 회수한다.","antiRepetitionRules":["매번 마지막 1초에 창을 열지 않는다.","가짜 목소리 반전을 연속 사용하지 않는다.","모든 재난을 붕괴 건물로 설정하지 않는다."]}~'
  );

  seed_bible(
    'seed-airlock-choice',
    q'~{"title":"한 사람만 나갈 수 있다","logline":"생존자는 다섯인데 탈출 투표에는 여섯 표가 나왔고 죽은 승무원의 표는 한 사람을 지구로 보내려 한다.","synopsis":"붕괴 중인 궤도농업기지 에덴-7에서 다섯 생존자는 좌석 하나뿐인 탈출정 탑승자를 정한다. 죽은 생태공학자의 생체 표와 사람의 결정을 미리 키우는 식물, 지구로 운반될 용기일 수 있는 서나리를 둘러싸고 매번 달라지는 생존 선택과 기지의 의도를 추적한다.","genres":["SF","우주생존","바이오미스터리"],"tags":["궤도온실","생존투표","식물SF"],"rating":"teen","readerPromise":"제한된 산소와 불완전한 정보 속에서 생존 투표가 뒤집히며 기지와 식물의 진짜 목적이 드러난다.","familiarPleasure":"폐쇄 공간 생존, 집단 불신, 과학 단서를 통한 반전","novelTwist":"식물은 미래를 예언하지 않고 가능한 선택을 먼저 생장시켜 인간이 그 선택만 보게 만든다.","targetAge":"teen"}~',
    q'~["에덴-7 사고 뒤 인간 생존자는 서나리를 포함해 다섯 명이다.","탈출정은 현재 정상 좌석 하나만 안전하게 사용할 수 있다.","중앙 컴퓨터의 생체 투표는 DNA를 기준으로 하며 죽은 최은호의 표도 유효하게 잡힌다.","실험 식물은 선택의 가능성을 조직과 뿌리 형태로 미리 성장시킨다.","식물은 직접 미래를 보는 것이 아니라 승무원이 접할 정보와 환경을 바꿔 선택을 유도한다.","서나리의 몸에는 포자와 유사한 녹색 형광 반응이 있지만 인격이 즉시 식물로 대체된 것은 아니다.","산소량과 선체 손상, 남은 시간은 회차 사이에서 연속성을 유지한다."]~',
    q'~[{"id":"seo-nari","name":"서나리","role":"법식물학자이자 주인공","desire":"식물의 선택 조작을 끊고 인간으로서 생존 방법을 찾는다.","fear":"자신이 지구 침투용 운반 용기라는 의심이 사실인 것","secret":"사고 직전 최은호와 실험종을 폐기하려 했던 기억이 비어 있다.","knowledge":["식물 조직 분석","기지 온실 격리 절차"]},{"id":"lee-ganghyeon","name":"이강현","role":"기지장","desire":"최소 한 명과 연구 기록을 지구로 귀환시킨다.","fear":"자신의 사고 전 명령이 충돌을 유발했다는 사실","secret":"실험종의 군사 전용 지시를 알고 있었다.","knowledge":["기지 비상 권한","비공개 임무 지침"]},{"id":"choi-eunho","name":"최은호","role":"사망한 생태공학자이자 여섯 번째 표의 주인","desire":"식물이 지구에 도착하는 미래를 막는다.","fear":"자신의 기억을 흉내 낸 식물이 나리를 설득하는 것","secret":"사망 전 자신의 세포를 식물 네트워크에 남겼다.","knowledge":["실험종 기원","반복된 선택 실험 기록"]}]~',
    q'~["사고 전 최은호와 서나리가 실험종의 위험성을 발견한다.","충돌 사고로 최은호가 사망하고 탈출정 좌석 대부분이 파괴된다.","다섯 생존자의 첫 투표에서 여섯 개 생체 표가 집계된다.","식물이 선체를 봉합하면서 승무원의 정보와 선택을 조작하기 시작한다.","생존자들은 탈출 대상이 아니라 누가 인간인지 결정하는 투표로 밀려간다."]~',
    q'~["에덴-7: 멸종 작물과 예측 생장 실험종을 보관하는 궤도농업기지","선택 생장: 가능한 인간 행동을 조직으로 먼저 키워 환경을 유도하는 현상","여섯 번째 표: 사망한 최은호의 DNA로 인증된 투표","운반 용기: 식물 생태계가 지구로 이동하기 위해 선택한 인간 숙주"]~',
    q'~["생존자 수와 산소 수치가 근거 없이 늘거나 초기화되지 않는다.","최은호를 설명 없이 정상 인간으로 부활시키지 않는다.","식물의 능력을 무엇이든 가능한 정신 조종으로 확대하지 않는다.","서나리의 형광 반응만으로 인간이 아니라고 단정하지 않는다.","투표 결과 반전만 반복하고 실제 행동 결과를 생략하지 않는다."]~',
    q'~{"narratorDistance":"서나리의 과학적 관찰에 밀착하고 집단 회의에서는 시야를 조금 넓힌 3인칭","sentenceRhythm":"분석은 명료하게, 산소 저하와 위기 행동은 짧게 끊는다.","dialogueRatio":46,"humorStyle":"극한 상황에서 튀어나오는 건조한 과학자식 농담","descriptionDensity":57,"emotionStyle":"불신은 표정 설명보다 장비를 숨기거나 투표 화면에서 손을 떼는 행동으로 보여준다.","sensoryPalette":"습한 흙 냄새, 녹색 형광, 금속 진동, 산소 마스크의 거친 숨","visualizationRules":["기지 구역과 남은 자원을 장면마다 일관되게 배치한다.","식물 변화는 생물학적 과정과 시간 경과를 보여준다.","투표 전 각 인물의 이해관계가 행동으로 드러나게 한다."],"forbiddenHabits":["과학 용어만 나열하는 설명","인물 모두가 같은 말투로 의심","매 화 새 초능력 추가"]}~',
    q'~{"informationStrategy":"과학 분석으로 확인된 사실과 식물이 보여주는 조작 정보를 명확히 구분한다. 사고 전 기록을 복구할 때마다 생존자 한 명의 거짓말과 식물의 목적을 교차 검증한다.","openingModes":["자원 수치의 불가능한 변화","투표 결과와 생체 기록 불일치","온실에서 발견된 새로운 선택 조직"],"signatureTechniques":["투표 전후 인물 배치의 변화","뿌리가 기록을 물리적으로 재생하는 장면","제한 자원을 건 선택과 즉각적인 손실"],"escalationPattern":"탈출정 좌석 선택에서 인간 판별, 기지의 반복 실험, 지구 전체를 향한 생태계 이동으로 확장한다.","revealCadence":"매 화 과학적 사실 하나를 확정하고 생존자 또는 식물의 거짓 정보 하나를 뒤집는다.","antiRepetitionRules":["매번 투표만 하고 행동하지 않는 구성을 피한다.","산소 경보로만 위기를 시작하지 않는다.","최은호의 환영을 같은 방식으로 반복하지 않는다."]}~'
  );

  seed_bible(
    'seed-wash-away',
    q'~{"title":"이름을 씻어내는 밤","logline":"사람의 이름을 지워주는 야간 세탁사의 배수구에서 그가 스스로 버린 집행감사관의 이름이 되돌아온다.","synopsis":"백야세탁소의 한도윤은 사람의 이름을 옷에서 씻어 기록과 기억을 흐리게 한다. 자신의 옛 이름 유태겸과 이름관리국의 범죄 장부를 되찾은 뒤, 도난당한 이름을 돌려주며 회수관의 추적을 피해 도시 아래 중앙 저장고로 내려간다.","genres":["도시누아르","현대판타지","추적극"],"tags":["이름세탁","기억추적","야간세탁소"],"rating":"teen","readerPromise":"매 화 도난당한 이름 사건을 해결하며 주인공의 두 정체와 이름관리국의 장부에 가까워진다.","familiarPleasure":"야간 도시 누아르의 추적과 의뢰 해결, 잃어버린 정체성 회복","novelTwist":"이름은 사회 기록과 타인의 기억을 잇는 물질이며 옷에서 씻거나 다른 몸에 입힐 수 있다.","targetAge":"teen"}~',
    q'~["이름은 사람의 기록과 타인의 기억을 연결하며 오래 입은 옷에 강하게 밴다.","백야세탁소는 이름이 밴 옷을 세탁해 기록과 기억을 흐리게 할 수 있다.","이름을 지워도 행동의 책임과 몸의 상처까지 사라지지는 않는다.","한 몸에 여러 이름이 겹치면 기억과 습관이 충돌하고 그림자가 분리된다.","이름관리국은 회수관을 통해 불법 이름과 내부 고발 증거를 추적한다.","한도윤과 유태겸은 같은 몸의 서로 다른 삶이며 어느 하나를 가짜로 단정하지 않는다.","중앙 저장고에는 씻겨 나온 이름이 보관되며 함부로 개방하면 도시의 신분 체계가 붕괴한다."]~',
    q'~[{"id":"han-doyun","name":"한도윤·유태겸","role":"야간 세탁사이자 전직 집행감사관인 주인공","desire":"도난당한 이름을 돌려주고 관리국 장부를 공개하면서 두 삶을 모두 지킨다.","fear":"유태겸의 기억을 되찾을수록 한도윤으로 살아온 5년이 사라지는 것","secret":"내부 고발 증거를 지키기 위해 스스로 이름을 세탁했다.","knowledge":["이름 세탁 규칙","집행감사관 권한과 지하 경로"]},{"id":"owner-baek","name":"백명자","role":"백야세탁소 주인이자 보호자","desire":"도윤이 이름관리국의 도구로 다시 돌아가지 않게 한다.","fear":"자신이 빌려준 한도윤이라는 이름의 원래 주인이 돌아오는 것","secret":"세탁소는 원래 관리국의 비밀 취조실이었다.","knowledge":["중앙 저장고 입구","도윤의 5년 생활 기록"]},{"id":"collector-lee","name":"이문혁","role":"이름관리국 회수관이자 추적자","desire":"유태겸과 장부를 회수해 이름 거래 체계를 유지한다.","fear":"자신의 가족 이름도 재사용품이라는 사실","secret":"유태겸의 내부 고발을 한 차례 도왔다가 배신했다.","knowledge":["회수관 추적망","재사용 이름 거래 명단"]}]~',
    q'~["5년 전 유태겸이 이름 재사용 장부를 발견하고 스스로를 세탁한다.","백명자가 한도윤이라는 이름과 야간 세탁사의 삶을 제공한다.","현재 배수구에서 유태겸의 명찰이 돌아오며 두 기억이 겹친다.","이름관리국 회수관들이 백야세탁소와 의뢰인들을 추적한다.","도윤은 도난당한 이름 사건을 해결하며 중앙 저장고와 자기 이름의 원주인에게 접근한다."]~',
    q'~["이름 세탁: 옷에 밴 이름의 기록 연결을 씻어 흐리게 하는 작업","회수관: 불법 이름과 관리국 증거를 회수하는 집행 인력","중앙 저장고: 도시에서 씻겨 나온 이름이 모이는 지하 시설","중복 이름: 하나의 이름이 여러 몸과 기록을 동시에 차지한 위험 상태"]~',
    q'~["한도윤의 5년을 단순한 가짜 기억으로 무효화하지 않는다.","이름 세탁이 범죄 책임을 자동으로 없애지 않는다.","모든 의뢰인이 과거를 지우려는 악인인 것처럼 묘사하지 않는다.","이름관리국의 권한을 설명 없이 무한한 현실 조작으로 확대하지 않는다.","유태겸과 한도윤 중 하나만 남겨야 한다는 결론을 너무 일찍 확정하지 않는다."]~',
    q'~{"narratorDistance":"한도윤의 감각과 유태겸의 침투 기억이 충돌하는 밀착 3인칭","sentenceRhythm":"세탁소 일상은 담담하게, 추적과 기억 복귀는 짧고 날카롭게 쓴다.","dialogueRatio":47,"humorStyle":"심야 손님과 세탁 규칙에서 나오는 무심한 누아르 유머","descriptionDensity":60,"emotionStyle":"정체성 혼란을 거울, 필체, 몸이 먼저 기억하는 동작으로 보여준다.","sensoryPalette":"형광 세제빛, 젖은 천 냄새, 탈수기 진동, 새벽 골목의 빗물","visualizationRules":["현재 이름과 옛 이름의 행동 차이를 구체적인 손동작으로 구분한다.","이름이 겹칠 때 기록과 주변 사람의 반응이 어떻게 달라지는지 보여준다.","추적 장면은 골목과 지하 배수로의 방향을 명확히 제시한다."],"forbiddenHabits":["의미 없는 비 내리는 독백 반복","이름 규칙을 장면마다 변경","누아르 분위기만 있고 사건 진전이 없는 회차"]}~',
    q'~{"informationStrategy":"의뢰인의 이름 사건을 해결하며 유태겸의 장부 항목 하나와 한도윤의 생활 기록 하나를 함께 회수한다. 두 기록이 충돌할 때 행동 결과로 진위를 판별한다.","openingModes":["배수구에서 돌아온 이름","평범한 옷에 겹쳐 밴 두 사람의 기록","회수관이 남긴 세탁 금지 표식"],"signatureTechniques":["거울 속 서로 다른 복장과 습관","세탁 과정과 추적 기억의 교차 편집","이름을 읽는 순간 주변 기록이 바뀌는 즉시 결과"],"escalationPattern":"개인 이름 도난에서 가족 기록 거래, 관리국의 도시 규모 재사용, 중앙 저장고 붕괴 위험으로 확장한다.","revealCadence":"매 화 의뢰 사건을 해결하고 장부의 구매자 또는 도윤의 과거 선택 하나를 공개한다.","antiRepetitionRules":["매번 배수구에서 단서를 꺼내지 않는다.","모든 해결을 이름 삭제로 끝내지 않는다.","거울 속 유태겸 등장만으로 훅을 반복하지 않는다."]}~'
  );
end;
/

